from pathlib import Path
import json,re,base64
root=Path('/Users/rohithpaull/build-sprint-app')
out=root/'content-team/jtbd-repair/opening'
def pic(label,fill=90,car=30,queue=True,before=False):
    rows=[]
    def row(y,title,level,pos,waiting):
        return f'''<text x="14" y="{y+18}" font-size="14" font-weight="700">{title}</text><path d="M34 {y+42} L42 {y+117} H94 L102 {y+42} Z" fill="#fff4fa" stroke="#35434b" stroke-width="3"/><path d="M44 {y+112} H92 V{y+112-level*.65} H44 Z" fill="#e885b1"/><path d="M76 {y+52} L87 {y+27} H102" fill="none" stroke="#35434b" stroke-width="4"/><text x="124" y="{y+50}" font-size="13">{('Till: waiting' if waiting else 'Till: cleared')}</text><path d="M126 {y+94} H324" stroke="#cad9df" stroke-width="8" stroke-linecap="round"/><text x="126" y="{y+117}" font-size="12">Shop</text><text x="294" y="{y+117}" font-size="12">Work</text><rect x="{126+pos}" y="{y+77}" width="27" height="15" rx="4" fill="#408cd0"/><circle cx="{132+pos}" cy="{y+94}" r="4" fill="#35434b"/><circle cx="{147+pos}" cy="{y+94}" r="4" fill="#35434b"/>'''
    rows.append(row(8,'Before · full cup at the shop',90,0,True))
    if not before: rows.append(row(149,label,fill,car,queue))
    svg='<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 350 '+('145' if before else '285')+'" font-family="system-ui" fill="#23343e">'+''.join(rows)+'</svg>'
    return {'type':'image','src':'data:image/svg+xml;base64,'+base64.b64encode(svg.encode()).decode(),'alt':('Full milkshake at the shop.' if before else 'Before: full cup at shop, waiting at till. After: '+label+'. '+('Still waiting at till.' if queue else 'Till cleared.'))}
def c(label,nxt,**kw):return dict(label=label,next=nxt,**kw)
sc={
'start':dict(mood='thinking',line='You run a fast-food chain. Make your morning milkshake worth coming back for. First instinct: easier to sip, or longer to finish? No score.',visual=pic('',before=True),choices=[c('I make it thinner.','thin',set={'recipe':'thin'}),c('I make it thicker.','thick',set={'recipe':'thick'})],note='Unscored intuition. Neither choice is a verdict on a real recipe. Schematic outcome follows.'),
 'thin':dict(mood='surprised',consequence=True,line='You made it easier to sip. Your cup finishes before this drive does.',visual={**pic('After · empty cup, road still ahead',0,105,False),'caption':'Illustrated possibility, not a measured recipe test.'},choices=[c('Follow the morning customer.','evidence')]),
 'thick':dict(mood='thinking',consequence=True,line='You made it slower to sip. Your cup lasts further into this drive.',visual={**pic('After · shake left, road still ahead',43,105,False),'caption':'Illustrated possibility, not a measured recipe test.'},choices=[c('Follow the morning customer.','evidence')]),
 'evidence':dict(mood='speaking',line='They were buying help getting through the drive: hold off hunger, occupy the journey, keep one hand free.',visual={'type':'cards','items':[{'title':'Morning observation','lines':['Most milkshakes sold before 8:30 a.m.','Those customers ordered no other food.']},{'title':'What else could do that job?','lines':['Other breakfast foods compete too.','Compare what happens during the drive.']}]},choices=[c('So what am I really improving?','name')]),
 'name':dict(mood='thinking',line='You changed a drink. Their situation tells you whether that change helps.',visual={'type':'concept','name':'Jobs to be Done','definition':'Look for the progress someone wants in a particular situation. Here: get through the commute without hunger or boredom—not merely drink a milkshake.'},choices=[c('Make the next product move.','second')]),
 'second':dict(mood='waiting',line='Now change the wait, not the drink. These regulars know their order and want to get on the road. What do you give them?',visual={'type':'cards','items':[{'title':'Next morning · imagined trial','lines':['Keep the thicker shake in both versions.','Prepay skips the till, but locks the order before arrival.','Pay at arrival keeps last-minute changes, but keeps the wait.']}]},choices=[c('I add prepay and quick pickup.','prepay'),c('I keep pay-and-change at arrival.','arrival')]),
 'prepay':dict(mood='surprised',consequence=True,line='You moved payment earlier. They leave the till sooner; the shake still lasts on the road. Two kinds of time. Two different fixes.',visual={**pic('After · pickup cleared, shake unchanged',90,45,False),'caption':'Imagined trial: prepay removes this till wait. Drink and drive length stay unchanged.'},choices=[c('Keep this product plan.','end')]),
 'arrival':dict(mood='thinking',consequence=True,line='You kept their freedom to change the order. These regulars still wait at the till. That tradeoff does not help them leave sooner.',visual={**pic('After · same cup, still at the till',90,0,True),'caption':'Imagined trial: keeping payment at arrival keeps this till wait.'},choices=[c('Move payment earlier for these regulars.','worked')]),
 'worked':dict(mood='speaking',line='Keep the shake slow. Make pickup fast. You removed time before the drive without removing something that fills the drive.',visual={**pic('After · pickup cleared, shake unchanged',90,45,False),'caption':'Worked plan for these regulars, not a rule for every customer.'},choices=[c('Keep this product plan.','end')]),
 'end':dict(mood='waiting',end=True,line='Before making a product “better,” ask: what progress does this person want here, and what else could help them get it?',visual={'type':'cards','items':[{'title':'Your commuter plan','lines':['Slow to finish. Fast to collect.']},{'title':'The next puzzle','lines':['Same shake, different occasion. Would this plan still help?']}]})}
deck={'meta':{'title':'Make the milkshake slower?','lesson':'Jobs to be Done','candidate':'milkshake-repair','lens':'Toy → changed circumstance','status':'Draft','author':'Independent Play Designer','humanTests':0},'start':'start','scenes':sc}
